const projects=[
{title:'ZERO THREE / 零叁',cat:'IP',subtitle:'半机械鼠与它的赛博世界',cover:4,range:[4,12],desc:'以半机械鼠零叁与搭档机器人零一为主角，构建赛博霓虹与废土城市中的温暖故事。涵盖角色设定、三视图、服饰、表情、场景及周边物料。'},
{title:'BAO PLAY / 爆玩',cat:'品牌',subtitle:'不一样的自己，也可以闪闪发光',cover:25,range:[14,32],desc:'以每一颗爆米花独特的形态为灵感，为解压捏捏盲盒建立年轻、有趣的品牌视觉。探索品牌策略、角色、标志、色彩、海报及包装的完整表达。'},
{title:'书页奇境，读书狂欢 YA',cat:'KV',subtitle:'世界读书日 · 喜马拉雅联名视觉',cover:35,range:[34,50],desc:'以治愈手绘插画呈现一个童趣的阅读世界，围绕有声阅读与沉浸式体验，延展海报、书签、开屏与线下场景。'},
{title:'云音人格图鉴',cat:'AIGC',subtitle:'音乐与自我的一次梦幻相遇',cover:55,range:[55,61],desc:'以梦幻云端与软萌黏土形象打造音乐人格测试活动的 H5 视觉方案，串联引导、答题、结果展示与分享体验。'},
{title:'AI MOTION / 影像实验',cat:'AIGC',subtitle:'从角色故事到 MV 与 TVC 分镜',cover:53,range:[52,54],desc:'通过 AIGC 探索 IP 动画、音乐影像与广告叙事的视觉语言。此处展示创意分镜与制作思路。'},
{title:'萌力全开！',cat:'KV',subtitle:'美团萌宠节 · 毛毡世界的快乐',cover:63,range:[63,65],desc:'以毛毡质感的萌宠与童话乐园为视觉中心，结合品牌黄色，营造温暖、活泼的活动氛围，延展系列主视觉与海报。'},
{title:'日常，也有新鲜灵感',cat:'AIGC',subtitle:'品牌运营视觉探索',cover:66,range:[66,68],desc:'围绕春日、开学季与生活场景，探索 AIGC 辅助下的品牌运营视觉表达与系列化设计。'},
{title:'春日甜品嘉年华',cat:'C4D',subtitle:'把快乐，装进一座微缩乐园',cover:70,range:[70,76],desc:'通过 Cinema 4D、Blender 与 Photoshop 构建春日甜品微缩场景，从建筑与道具到昼夜氛围，延展活动主视觉与艺术海报。'}];
const categories=['全部','IP','品牌','KV','AIGC','C4D'];let current=0,lastFocus;
const grid=document.querySelector('#projects'),dialog=document.querySelector('#detail');
function render(cat='全部'){grid.innerHTML=projects.map((p,i)=>({p,i})).filter(({p})=>cat==='全部'||p.cat===cat).map(({p,i})=>`<button class="project reveal" data-project="${i}"><div class="project-image"><img src="assets/${p.cover}.jpg" alt="${p.title}" loading="lazy"><span class="view">查看项目 ↗</span><span class="number">${String(i+1).padStart(2,'0')}</span></div><div class="project-meta"><div><h3>${p.title}</h3><p>${p.subtitle}</p></div><span>${p.cat} DESIGN ↗</span></div></button>`).join('');observe();}
document.querySelector('.filters').innerHTML=categories.map((c,i)=>`<button class="${i?'':'active'}" aria-pressed="${!i}" data-filter="${c}">${c}${i===0?' / ALL':''}</button>`).join('');
document.querySelector('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render(b.dataset.filter)};
function openProject(i){current=i;const p=projects[i];document.querySelector('#detail-label').textContent=`SIWEI CAO / PROJECT ${String(i+1).padStart(2,'0')}`;document.querySelector('#detail-cat').textContent=p.cat+' DESIGN / 2026';document.querySelector('#detail-title').textContent=p.title;document.querySelector('#detail-desc').textContent=p.desc;document.querySelector('#detail-images').innerHTML=Array.from({length:p.range[1]-p.range[0]+1},(_,j)=>p.range[0]+j).filter(n=>n!==44).map((n,j)=>`<img src="assets/${n}.jpg" alt="${p.title} · 项目展示 ${j+1}" loading="${j?'lazy':'eager'}">`).join('');if(!dialog.open){lastFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden'}dialog.scrollTop=0;}
grid.onclick=e=>{const b=e.target.closest('[data-project]');if(b)openProject(+b.dataset.project)};document.querySelector('#next').onclick=()=>openProject((current+1)%projects.length);document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});function observe(){document.querySelectorAll('.reveal').forEach(x=>observer.observe(x))}render();
document.querySelector('#wechat').onclick=async()=>{try{await navigator.clipboard.writeText('sui041003');document.querySelector('.toast').textContent='微信号已复制：sui041003'}catch{document.querySelector('.toast').textContent='微信号：sui041003'}document.querySelector('.toast').classList.add('show');setTimeout(()=>document.querySelector('.toast').classList.remove('show'),3000)};
addEventListener('scroll',()=>{document.querySelector('.progress').style.width=100*scrollY/(document.documentElement.scrollHeight-innerHeight)+'%'},{passive:true});
if(matchMedia('(hover:hover) and (prefers-reduced-motion:no-preference)').matches){document.querySelector('.hero').addEventListener('pointermove',e=>{document.querySelector('.collage').style.setProperty('--move',`${(e.clientX/innerWidth-.5)*12}px`)})}
